    fun mergeWith(existing: List<RealWorldMediaItem>): List<RealWorldMediaItem> {
        val byTitle = existing.associateBy { it.category to it.title }
        val byId = existing.associateBy { it.id }
        val bundled = pictures.map { picture ->
            val category = picture.category
            val old = byTitle[category to picture.existingTitle]
            val id = old?.id ?: "atlas_${picture.id}"
            val item = old ?: RealWorldMediaItem(
                id, category, picture.title, picture.group,
                if (category == RealMediaCategory.ANIMAL) "🐾" else "🔎", picture.group,
                emptyList(), "Picture card", 392f, ReelMotionStyle.SOUND_WAVE_PULSE,
                Color(0xFF0E7490), Color(0xFF164E63),
                manifest = manifest(id, picture.path, picture.checksum)
            )
            item.copy(
                title = picture.title, subtitle = picture.group, habitatOrGroup = picture.group,
                funFacts = listOf(picture.fact), subtitles = listOf(picture.fact),
                bundledDrawableRes = picture.image, bundledSoundRes = picture.sound,
                bundledVideoRes = picture.video, manifest = manifest(id, picture.path, picture.checksum)
            )
        }
        val films = lessons.map { lesson ->
            val id = byId[lesson.existingId]?.id ?: lesson.id
            RealWorldMediaItem(
                id, RealMediaCategory.FILM_LESSON, lesson.title, "${lesson.duration}-second offline lesson",
                "🎬", lesson.topic, listOf(lesson.topic), "Recorded English narration", 392f,
                ReelMotionStyle.STORY_LESSON_SCENE, Color(0xFF5B21B6), Color(0xFF312E81),
                bundledDrawableRes = lesson.image, bundledVideoRes = lesson.video,
                bundledCaptionsRes = lesson.captions,
                manifest = manifest(id, lesson.path, lesson.checksum, lesson.duration)
            )
        }
        val replacements = (bundled + films).associateBy { it.id }
        // Surface the ready-to-play lessons and illustrated cards before legacy fallbacks.
        return existing.filter { it.id in replacements || it.bundledVideoRes != null }
            .map { replacements[it.id] ?: it } +
            (bundled + films).filterNot { it.id in byId } +
            existing.filter { it.id !in replacements && it.bundledVideoRes == null }
    }

    private fun manifest(id: String, path: String, checksum: String, duration: Int = 0) =
        MediaManifestEntry(
            id, path, if (duration > 0) "MP4 with English captions" else "Picture",
            duration, checksum, "Little Wonder World Complete Media Pack",
            "Little Wonder World Original Production", AssetVerificationStatus.BUNDLED_VERIFIED,
            "Use the card illustration or description"
        )
}
